import { describe, expect, test } from "bun:test";
import {
  MINIMAL_BEADS_POINTER,
  minimizeBeadsInstructions,
  minimizeSystemParts,
} from "../src/instructions";

const USER_BEFORE = "# Agent Instructions\n\nProject rules written by the user.\n\n\n\nKeep this spacing.";
const FULL_BLOCK = [
  "<!-- BEGIN BEADS INTEGRATION v:1 profile:full hash:9c890b20 -->",
  "## Issue Tracking with bd (beads)",
  "Long command reference duplicated by bd prime.",
  "<!-- END BEADS INTEGRATION -->",
].join("\n");
const CODEX_BLOCK = [
  "<!-- BEGIN BEADS CODEX SETUP: generated by bd setup codex -->",
  "## Beads Issue Tracker",
  "Codex quick reference.",
  "<!-- END BEADS CODEX SETUP -->",
].join("\n");
const MINIMAL_BLOCK = [
  "<!-- BEGIN BEADS INTEGRATION v:1 profile:minimal hash:1105d646 -->",
  "## Beads Issue Tracker",
  "Run `bd prime` to see full workflow context and commands.",
  "<!-- END BEADS INTEGRATION -->",
].join("\n");
const USER_AFTER = "## Release process\n\nUser-owned section.";

describe("minimizeBeadsInstructions", () => {
  test("collapses bd's full-profile and Codex blocks into one pointer", () => {
    const text = [USER_BEFORE, FULL_BLOCK, CODEX_BLOCK, USER_AFTER].join("\n\n");
    const result = minimizeBeadsInstructions(text);
    expect(result.replaced).toBe(2);
    expect(result.text).toBe([USER_BEFORE, MINIMAL_BEADS_POINTER, "", USER_AFTER].join("\n\n"));
    expect(result.text.match(/opencode-beads plugin/g)).toHaveLength(1);
    expect(result.text).not.toContain("BEGIN BEADS");
  });

  test("leaves minimal-profile blocks and text without bd blocks unchanged", () => {
    const minimal = [USER_BEFORE, MINIMAL_BLOCK, USER_AFTER].join("\n\n");
    expect(minimizeBeadsInstructions(minimal)).toEqual({ text: minimal, replaced: 0 });
    expect(minimizeBeadsInstructions(USER_BEFORE)).toEqual({ text: USER_BEFORE, replaced: 0 });
  });

  test("never removes an unterminated block", () => {
    const unterminated = `${USER_BEFORE}\n\n<!-- BEGIN BEADS INTEGRATION v:1 profile:full hash:x -->\ntruncated`;
    expect(minimizeBeadsInstructions(unterminated)).toEqual({ text: unterminated, replaced: 0 });
  });
});

describe("minimizeSystemParts", () => {
  test("rewrites only text parts that contain bd blocks", () => {
    const parts = [
      { type: "text", text: "You are an AI agent running in OpenCode." },
      { type: "text", text: `Instructions from: /repo/AGENTS.md\n${FULL_BLOCK}` },
      { type: "image" },
    ];
    expect(minimizeSystemParts(parts)).toBe(1);
    expect(parts[0]?.text).toBe("You are an AI agent running in OpenCode.");
    expect(parts[1]?.text).toBe(`Instructions from: /repo/AGENTS.md\n${MINIMAL_BEADS_POINTER}`);
  });
});

